const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:8px;color:var(--ink);font-size:13px;line-height:1.35;overflow:hidden}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;cursor:pointer}\n.page{flex:1 1 auto;min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden}\n.page>*{flex:1 1 auto;min-width:0;min-height:0}\n.home{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:0}\n.topbar{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.tabs{flex:1;min-width:0;display:flex;gap:2px;padding:2px;border-radius:10px;background:var(--soft)}\n.tab{flex:1;min-width:0;border:0;border-radius:8px;padding:4px 6px;background:transparent;color:var(--muted);font-size:12px;white-space:nowrap}\n.tab.on{background:var(--panel-paper);color:var(--ink);font-weight:700;box-shadow:0 0 0 1px var(--line)}\n.add{flex:none;height:28px;min-width:30px;padding:0 10px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-weight:700;white-space:nowrap}\n.card button.add{color:var(--on-accent)}\n.lbl{display:none}\n.card[data-size=\"6x3\"] .lbl,.card[data-size=\"6x6\"] .lbl{display:inline}\n.sum{flex:none;display:none;font-size:12px;color:var(--muted)}\n.card[data-size=\"3x6\"] .sum,.card[data-size=\"6x6\"] .sum{display:block}\n.scroll{flex:1 1 auto;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:4px;padding-right:2px}\n.ctl{flex:none;display:flex;flex-wrap:wrap;justify-content:space-between;gap:0 8px}\n.lnk{border:0;background:transparent;padding:2px 0;font-size:11px;color:var(--muted);text-decoration:underline;text-underline-offset:2px}\n.list{display:grid;grid-template-columns:repeat(auto-fill,minmax(172px,1fr));gap:6px;align-content:start}\n.book{position:relative;min-width:0;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.book.stale{border-color:var(--accent);border-left-width:4px}\n.main{width:100%;min-width:0;display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:6px;row-gap:4px;align-items:center;text-align:left;border:0;border-radius:10px;padding:7px 8px;background:transparent;color:var(--ink)}\n.t{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:700}\n.pct{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}\n.bar{grid-column:1/-1;display:block;height:6px;border-radius:3px;background:var(--soft);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:3px;background:var(--accent)}\n.meta{grid-column:1/-1;min-width:0;min-height:22px;display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;padding-right:46px;font-size:11px;color:var(--muted)}\n.done .meta{padding-right:0;min-height:0}\n.when.warn{padding:1px 6px;border:1px solid var(--accent);border-radius:6px;background:var(--soft);color:var(--ink);font-weight:700}\n.rec{position:absolute;right:6px;bottom:6px;height:22px;padding:0 9px;border:1px solid var(--accent);border-radius:8px;background:var(--button-paper,var(--paper));color:var(--ink);font-size:11px}\n.empty{margin:auto;display:flex;flex-direction:column;align-items:center;gap:8px;padding:8px;color:var(--muted);text-align:center}\n.dt{display:flex;flex-direction:column;gap:8px;min-width:0}\n.big{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}\n.big b{font-size:28px;line-height:1.1}\n.big span{color:var(--muted)}\n.kvr{display:flex;gap:10px;font-size:12px;min-width:0}\n.k{flex:none;min-width:4em;color:var(--muted)}\n.v{min-width:0;overflow-wrap:anywhere}\n.warnline{padding:6px 8px;border:1px solid var(--accent);border-radius:8px;background:var(--soft);font-size:12px;font-weight:700}\n.note{font-size:12px;color:var(--muted)}\n";
function arr(x){return Array.isArray(x)?x:[];}

function dayNum(s){
  const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s||''));
  if(!m)return null;
  return Date.UTC(+m[1],+m[2]-1,+m[3])/86400000;
}

// 记录进度：页码到达总页数时移入历史
function applyProgress(s,id,cur,date){
  const bs=arr(s.books).slice();
  const i=bs.findIndex(x=>x.id===id);
  if(i<0)return s;
  const b=bs[i];
  if(cur>=b.total){
    bs.splice(i,1);
    const e=Object.assign({},b,{current:b.total,lastRead:date,finishedAt:date,prevCurrent:b.current,prevLastRead:b.lastRead||''});
    return Object.assign({},s,{books:bs,history:[e].concat(arr(s.history))});
  }
  bs[i]=Object.assign({},b,{current:cur,lastRead:date});
  return Object.assign({},s,{books:bs});
}

function restoreBook(s,id,today){
  const e=arr(s.history).find(x=>x.id===id);
  if(!e)return s;
  const pc=(Number.isInteger(e.prevCurrent)&&e.prevCurrent<e.total)?e.prevCurrent:0;
  const b={id:e.id,title:e.title,total:e.total,current:pc,lastRead:pc>0?(e.prevLastRead||''):'',addedAt:e.addedAt||today};
  return Object.assign({},s,{
    history:arr(s.history).filter(x=>x.id!==id),
    books:[b].concat(arr(s.books))
  });
}

function removeBook(s,id){
  return Object.assign({},s,{books:arr(s.books).filter(x=>x.id!==id)});
}

function removeHistory(s,id){
  return Object.assign({},s,{history:arr(s.history).filter(x=>x.id!==id)});
}

function editBook(s,id,title,total){
  return Object.assign({},s,{books:arr(s.books).map(x=>x.id===id?Object.assign({},x,{title:title,total:total}):x)});
}

function sortBooks(list,mode){
  const a=list.slice();
  const key=b=>b.lastRead||b.addedAt||'';
  a.sort((x,y)=>{
    let c=0;
    if(mode==='recent')c=key(y).localeCompare(key(x));
    else if(mode==='progress')c=(y.current/y.total)-(x.current/x.total);
    else c=key(x).localeCompare(key(y));
    return c||String(x.title).localeCompare(String(y.title));
  });
  return a;
}


function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day,percent,editor,panel}=ctx;
  if(!ui.tab)ui.tab='reading';
  if(!ui.sort)ui.sort='stale';
  if(!ui.mode)ui.mode='list';
  const books=arr(state.books),hist=arr(state.history);
  const staleDays=(Number.isInteger(state.staleDays)&&state.staleDays>=1)?state.staleDays:14;
  const today=day();
  const SORTS={stale:'久未读优先',recent:'最近读优先',progress:'进度高优先'};
  const ORDER=['stale','recent','progress'];
  const findBook=id=>books.find(b=>b.id===id);
  const findHist=id=>hist.find(b=>b.id===id);
  const nextUi=p=>Object.assign({tab:ui.tab,sort:ui.sort,mode:'list',id:null,from:null,draft:null,confirm:null},p||{});
  const go=p=>{Object.assign(ui,{mode:'list',id:null,from:null,draft:null,confirm:null},p||{});redraw();};
  const run=pr=>{if(pr&&pr.catch)pr.catch(()=>{});};
  const back=()=>{if(ui.from==='detail'&&ui.id)go({mode:'detail',id:ui.id});else go();};

  const daysSince=s=>{const a=dayNum(s),b=dayNum(today);return a===null?null:Math.max(0,Math.round(b-a));};
  const pctOf=(c,t)=>{if(c>=t)return 100;return Math.min(99,Math.max(0,Math.round(percent(c,t))));};
  // 距上次阅读的天数；没有阅读日期且尚未开始的书，从添加日起算
  const idleDays=b=>{const ref=b.lastRead||(b.current>0?'':b.addedAt);return ref?daysSince(ref):null;};
  const isStale=b=>{const d=idleDays(b);return d!==null&&d>=staleDays;};
  const whenText=b=>{
    const d=idleDays(b);
    if(!b.lastRead&&b.current>0)return '未记录日期';
    if(isStale(b))return (b.lastRead?'久未读 ':'未开始 ')+d+'天';
    if(!b.lastRead)return '尚未开始';
    return d===0?'今天读过':d===1?'昨天读过':d+'天前读过';
  };

  const openAdd=()=>go({mode:'add',draft:{title:'',total:'',current:'',date:''}});
  const openSettings=()=>go({mode:'settings',draft:{staleDays:String(staleDays)}});
  const openUpdate=(b,from)=>go({mode:'update',id:b.id,from:from,draft:{current:String(b.current),date:today}});
  const openEdit=b=>go({mode:'edit',id:b.id,from:'detail',draft:{title:b.title,total:String(b.total)}});
  const openDetail=b=>go({mode:'detail',id:b.id});
  const openHist=e=>go({mode:'hdetail',id:e.id});

  function addForm(){
    return editor({title:'添加书籍',draft:ui.draft||{},submitLabel:'添加',onBack:back,
      fields:[
        {key:'title',label:'书名',type:'text',required:true,placeholder:'例如：三体'},
        {key:'total',label:'总页数',type:'number',required:true,min:1,step:1},
        {key:'current',label:'当前页码（选填，默认 0；等于总页数则直接记为读完）',type:'number',min:0,step:1},
        {key:'date',label:'最近阅读日期（选填；页码大于 0 时默认今天）',type:'date'}
      ],
      onSave:v=>{
        const title=String(v.title||'').trim();
        if(!title)return '请填写书名';
        if(v.total===''||v.total==null)return '请填写总页数';
        const total=Number(v.total);
        if(!Number.isInteger(total)||total<1)return '总页数需为不小于 1 的整数';
        const cur=(v.current===''||v.current==null)?0:Number(v.current);
        if(!Number.isInteger(cur)||cur<0||cur>total)return '当前页码需为 0 到 '+total+' 的整数';
        let date=String(v.date||'');
        if(date&&!dayNum(date))return '日期格式不正确';
        if(date>today)return '阅读日期不能晚于今天';
        if(cur===0)date='';
        else if(!date)date=today;
        const id=uid();
        if(cur>=total){
          const e={id:id,title:title,total:total,current:total,addedAt:today,lastRead:date,finishedAt:date};
          return commit(s=>Object.assign({},s,{history:[e].concat(arr(s.history))}),nextUi({tab:'history'}));
        }
        const b={id:id,title:title,total:total,current:cur,lastRead:date,addedAt:today};
        return commit(s=>Object.assign({},s,{books:[b].concat(arr(s.books))}),nextUi({tab:'reading'}));
      }});
  }

  function updateForm(b){
    return editor({title:'记录进度：'+b.title,draft:ui.draft||{},submitLabel:'保存',onBack:back,
      fields:[
        {key:'current',label:'当前页码（0–'+b.total+'；填 '+b.total+' 即读完并进入历史）',type:'number',required:true,min:0,max:b.total,step:1},
        {key:'date',label:'阅读日期',type:'date',required:true}
      ],
      onSave:v=>{
        if(v.current===''||v.current==null)return '请填写当前页码';
        const cur=Number(v.current);
        if(!Number.isInteger(cur)||cur<0||cur>b.total)return '页码需为 0 到 '+b.total+' 的整数';
        const date=String(v.date||'');
        if(!dayNum(date))return '请选择阅读日期';
        if(date>today)return '阅读日期不能晚于今天';
        const id=b.id;
        const nu=cur>=b.total?nextUi({tab:'history'}):(ui.from==='detail'?nextUi({mode:'detail',id:id}):nextUi());
        return commit(s=>applyProgress(s,id,cur,date),nu);
      }});
  }

  function editForm(b){
    return editor({title:'编辑书籍',draft:ui.draft||{},submitLabel:'保存',onBack:back,
      fields:[
        {key:'title',label:'书名',type:'text',required:true},
        {key:'total',label:'总页数',type:'number',required:true,min:1,step:1}
      ],
      onSave:v=>{
        const title=String(v.title||'').trim();
        if(!title)return '请填写书名';
        const total=Number(v.total);
        if(v.total===''||!Number.isInteger(total)||total<1)return '总页数需为不小于 1 的整数';
        if(total<=b.current)return '总页数需大于当前页码 '+b.current+'；读完请用「读完了」';
        const id=b.id;
        return commit(s=>editBook(s,id,title,total),nextUi({mode:'detail',id:id}));
      }});
  }

  function settingsForm(){
    return editor({title:'久未读提醒',draft:ui.draft||{},submitLabel:'保存',onBack:back,
      fields:[{key:'staleDays',label:'超过多少天没读算「久未读」',type:'number',required:true,min:1,max:365,step:1}],
      onSave:v=>{
        const n=Number(v.staleDays);
        if(v.staleDays===''||!Number.isInteger(n)||n<1||n>365)return '天数需为 1 到 365 的整数';
        return commit(s=>Object.assign({},s,{staleDays:n}),nextUi());
      }});
  }


  const infoRow=(k,v)=>el('div',{class:'kvr'},el('span',{class:'k'},k),el('span',{class:'v'},v));
  const barOf=p=>el('span',{class:'bar'},el('i',{style:'width:'+p+'%'}));

  function detailView(b){
    const p=pctOf(b.current,b.total),d=idleDays(b),confirming=ui.confirm===b.id;
    const kids=[
      el('div',{class:'big'},el('b',{},p+'%'),el('span',{},b.current+' / '+b.total+' 页')),
      barOf(p),
      infoRow('还剩',(b.total-b.current)+' 页'),
      infoRow('最近阅读',b.lastRead?(b.lastRead+'（'+(d===0?'今天':d+' 天前')+'）'):(b.current>0?'未记录':'尚未开始'))
    ];
    if(isStale(b))kids.push(el('div',{class:'warnline'},'久未读：已 '+d+' 天没动，超过 '+staleDays+' 天的提醒线'));
    kids.push(infoRow('添加于',b.addedAt||'未记录'));
    if(confirming)kids.push(el('div',{class:'warnline'},'再点一次「确认删除」将永久删除这本书的记录。'));
    return panel({title:b.title,body:el('div',{class:'dt'},...kids),onBack:()=>go(),actions:[
      {label:'更新进度',primary:true,onClick:()=>openUpdate(b,'detail')},
      {label:'读完了',onClick:()=>run(commit(s=>applyProgress(s,b.id,b.total,today),nextUi({tab:'history'})))},
      {label:'编辑',onClick:()=>openEdit(b)},
      {label:confirming?'确认删除':'删除',onClick:()=>{
        if(confirming)run(commit(s=>removeBook(s,b.id),nextUi()));
        else{ui.confirm=b.id;redraw();}
      }}
    ]});
  }

  function histDetail(e){
    const confirming=ui.confirm===e.id;
    const pc=(Number.isInteger(e.prevCurrent)&&e.prevCurrent<e.total)?e.prevCurrent:0;
    const kids=[
      el('div',{class:'big'},el('b',{},'已读完'),el('span',{},'共 '+e.total+' 页')),
      infoRow('读完日期',e.finishedAt||'未记录'),
      infoRow('添加于',e.addedAt||'未记录'),
      el('div',{class:'note'},'移回在读后，进度回到第 '+pc+' 页'+(pc===0?'（从头重读）':'（读完前的页码）')+'。')
    ];
    if(confirming)kids.push(el('div',{class:'warnline'},'再点一次「确认删除」将永久删除这条历史记录。'));
    return panel({title:e.title,body:el('div',{class:'dt'},...kids),onBack:()=>go({tab:'history'}),actions:[
      {label:'移回在读',primary:true,onClick:()=>run(commit(s=>restoreBook(s,e.id,today),nextUi({tab:'reading'})))},
      {label:confirming?'确认删除':'删除',onClick:()=>{
        if(confirming)run(commit(s=>removeHistory(s,e.id),nextUi({tab:'history'})));
        else{ui.confirm=e.id;redraw();}
      }}
    ]});
  }

  function bookRow(b){
    const p=pctOf(b.current,b.total),st=isStale(b);
    return el('div',{class:'book'+(st?' stale':'')},
      el('button',{type:'button',class:'main',title:b.title,'aria-label':'查看《'+b.title+'》详情',onclick:()=>openDetail(b)},
        el('span',{class:'t'},b.title),
        el('span',{class:'pct'},p+'%'),
        barOf(p),
        el('span',{class:'meta'},el('span',{class:'pg'},b.current+'/'+b.total+'页'),el('span',{class:'when'+(st?' warn':'')},whenText(b)))),
      el('button',{type:'button',class:'rec','aria-label':'记录《'+b.title+'》的阅读进度',onclick:()=>openUpdate(b,'list')},'记录'));
  }

  function histRow(e){
    return el('div',{class:'book done'},
      el('button',{type:'button',class:'main',title:e.title,'aria-label':'查看《'+e.title+'》历史记录',onclick:()=>openHist(e)},
        el('span',{class:'t'},e.title),
        el('span',{class:'pct'},'读完'),
        el('span',{class:'meta'},el('span',{class:'pg'},(e.finishedAt||'日期未记录')+' · 共'+e.total+'页'))));
  }

  const tabBtn=(key,label,n)=>el('button',{type:'button',class:'tab'+(ui.tab===key?' on':''),onclick:()=>{if(ui.tab!==key)go({tab:key});}},label+' '+n);

  function listView(){
    const reading=ui.tab==='reading';
    const nStale=books.filter(isStale).length;
    const sc=el('div',{class:'scroll'});
    if(reading){
      if(!books.length){
        sc.append(el('div',{class:'empty'},el('span',{},'还没有在读的书'),el('button',{type:'button',class:'add',onclick:openAdd},'添加第一本书')));
      }else{
        sc.append(el('div',{class:'ctl'},
          el('button',{type:'button',class:'lnk',onclick:()=>{ui.sort=ORDER[(ORDER.indexOf(ui.sort)+1)%ORDER.length];redraw();}},'排序：'+SORTS[ui.sort]),
          el('button',{type:'button',class:'lnk',onclick:openSettings},'久未读 ≥'+staleDays+'天')));
        sc.append(el('div',{class:'list'},...sortBooks(books,ui.sort).map(bookRow)));
      }
    }else if(!hist.length){
      sc.append(el('div',{class:'empty'},el('span',{},'读完的书会收进这里')));
    }else{
      const hs=hist.slice().sort((a,b)=>String(b.finishedAt||'').localeCompare(String(a.finishedAt||'')));
      sc.append(el('div',{class:'list'},...hs.map(histRow)));
    }
    return el('div',{class:'home'},
      el('div',{class:'topbar'},
        el('div',{class:'tabs'},tabBtn('reading','在读',books.length),tabBtn('history','历史',hist.length)),
        el('button',{type:'button',class:'add','aria-label':'添加书籍',onclick:openAdd},'+',el('span',{class:'lbl'},' 添加'))),
      el('div',{class:'sum'},'在读 '+books.length+' 本 · 久未读 '+nStale+' 本 · 已读完 '+hist.length+' 本'),
      sc);
  }

  const bk=ui.id?findBook(ui.id):null,he=ui.id?findHist(ui.id):null;
  let view;
  if(ui.mode==='add')view=addForm();
  else if(ui.mode==='settings')view=settingsForm();
  else if(ui.mode==='update'&&bk)view=updateForm(bk);
  else if(ui.mode==='edit'&&bk)view=editForm(bk);
  else if(ui.mode==='detail'&&bk)view=detailView(bk);
  else if(ui.mode==='hdetail'&&he)view=histDetail(he);
  else{ui.mode='list';view=listView();}
  root.append(el('div',{class:'page'},view));
}

